// ReviewScorecardTable.tsx — Image 7 exact UI
import React, { useState } from "react";
import styles from "./ReviewScorecardTable.module.scss";
import { ReviewScorecardJob } from "../../services/IEvaluationService";


type SortKey = keyof Pick<ReviewScorecardJob, "jobCode" | "jobTitle" | "businessUnitCode" | "positionRequest" | "nationality">;

interface Props {
  jobs:        ReviewScorecardJob[];
  loading:     boolean;
  onReview:    (job: ReviewScorecardJob) => void;
  onNavigate:  (path: string) => void;
}

const SortArrow: React.FC<{ col: SortKey; sk: SortKey; sd: "asc" | "desc" }> = ({ col, sk, sd }) => (
  <span className={styles.sortIcon}>{sk === col ? (sd === "asc" ? "↑" : "↓") : "↑↓"}</span>
);

const ReviewScorecardTable: React.FC<Props> = ({ jobs, loading, onReview, onNavigate }) => {
  const [sk, setSk]       = useState<SortKey>("jobCode");
  const [sd, setSd]       = useState<"asc" | "desc">("asc");
  const [page, setPage]   = useState(1);
  const [perPage, setPerPage] = useState<number>(5);

  const handleSort = (col: SortKey) => {
    setSd(d => sk === col ? (d === "asc" ? "desc" : "asc") : "asc");
    setSk(col);
    setPage(1);
  };

  const sorted = [...jobs].sort((a, b) => {
    const va = String(a[sk] ?? "");
    const vb = String(b[sk] ?? "");
    return sd === "asc" ? va.localeCompare(vb) : vb.localeCompare(va);
  });

  const total = Math.ceil(sorted.length / perPage) || 1;
  const safe  = Math.min(page, total);
  const start = (safe - 1) * perPage;
  const paged = sorted.slice(start, start + perPage);

  const TH: React.FC<{ col: SortKey; label: string }> = ({ col, label }) => (
    <th className={styles.th} onClick={() => handleSort(col)}>
      {label} <SortArrow col={col} sk={sk} sd={sd} />
    </th>
  );

  if (loading) return (
    <div className={styles.wrapper}>
      {Array.from({ length: 5 }, (_, i) => (
        <div key={i} className={styles.skRow}>
          {[80, 280, 120, 160, 100, 180, 80].map((w, j) => (
            <span key={j} className={styles.shimmer} style={{ width: w }} />
          ))}
        </div>
      ))}
    </div>
  );

  return (
    <div className={styles.wrapper}>
      <table className={styles.table}>
        <thead>
          <tr>
            <TH col="jobCode"          label="JOB CODE"           />
            <TH col="jobTitle"         label="JOB TITLE"          />
            <TH col="businessUnitCode" label="BUSINESSUNIT CODE"  />
            <TH col="positionRequest"  label="POSITION REQUEST"   />
            <TH col="nationality"      label="NATIONALITY"        />
            <th className={styles.th}>STATUS</th>
            <th className={styles.th}>ACTION</th>
          </tr>
        </thead>
        <tbody>
          {paged.map((job) => (
            <tr key={job.id} className={styles.row}>
              {/* Image 7: Job code in blue */}
              <td><span className={styles.jobCode}>{job.jobCode}</span></td>
              <td className={styles.jobTitle}>{job.jobTitle}</td>
              <td className={styles.cell}>{job.businessUnitCode}</td>
              <td className={styles.cell}>{job.positionRequest}</td>
              <td className={styles.cell}>{job.nationality}</td>
              <td>
                <div className={styles.statusWrap}>
                  <span className={styles.statusDot} />
                  <span className={styles.cell}>{job.status}</span>
                </div>
              </td>
              <td>
                {/* Image 7: blue "REVIEW" button */}
                <button className={styles.reviewBtn} onClick={() => onReview(job)}>
                  REVIEW
                </button>
              </td>
            </tr>
          ))}
          {paged.length === 0 && <tr><td colSpan={7} className={styles.empty}>No jobs found.</td></tr>}
        </tbody>
      </table>

      {/* Same footer style as EvaluationTable */}
      {sorted.length > 0 && (
        <div className={styles.footer}>
          <span className={styles.showLabel}>
            Showing <b>{start + 1}</b> to <b>{Math.min(start + perPage, sorted.length)}</b> of <b>{sorted.length}</b> results
          </span>
          <div className={styles.showEntries}>
            <span>SHOW</span>
            <select className={styles.perPageSel} value={perPage} onChange={e => { setPerPage(Number(e.target.value)); setPage(1); }}>
              {[5, 10, 25, 50].map(n => <option key={n} value={n}>{n}</option>)}
            </select>
            <span>ENTRIES</span>
          </div>
          <div className={styles.pageBtns}>
            <button className={styles.pageBtn} onClick={() => setPage(p => Math.max(p - 1, 1))} disabled={safe === 1}>‹</button>
            {Array.from({ length: total }, (_, i) => (
              <button key={i} className={`${styles.pageBtn} ${safe === i + 1 ? styles.pageBtnActive : ""}`} onClick={() => setPage(i + 1)}>{i + 1}</button>
            ))}
            <button className={styles.pageBtn} onClick={() => setPage(p => Math.min(p + 1, total))} disabled={safe === total}>›</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ReviewScorecardTable;